import React from 'react';
import { createRoot } from 'react-dom/client';
import { RelationshipGraph } from '../../src/components/studios/lorebook/RelationshipGraph';
import type { DocumentMetadata } from '../../src/types';
import '../../src/index.css';
const doc = (id: string, entry_type: string, fields = {}): DocumentMetadata => ({ id, title: id === 'character' ? 'Voltaire Manus' : 'Central Body of Humanity', doc_type: 'lorebook', house_id: 'house-default', relative_path: '', created_at: '', updated_at: '', tags: [], metadata_json: JSON.stringify({ universe_id: 'u', entry_type, faction_fields: fields }) });
const documents = [doc('character', 'character'), doc('faction', 'faction', { branches: [{ id: 'navy', name: 'Navy' }], positions: [{ id: 'emperor', title: 'Cognitive Emperor', holder_ids: ['character'] }, { id: 'admiral', title: 'Galactic Admiral', branch_id: 'navy', holder_ids: ['character'] }] })];
const opened: string[] = [];
createRoot(document.getElementById('root')!).render(<RelationshipGraph universeId="u" documents={documents} name={id => documents.find(d => d.id === id)?.title || id} onOpenEntity={id => opened.push(id)} rows={[{ relationship: { id: 'membership', universe_id: 'u', source_id: 'character', target_id: 'faction', label: 'Member of', description: 'Explicit authored affiliation', directed: true, archived: false, book_id: null, context_node_id: null }, evidence: { value: 'Member of', kind: 'baseline', source: null, conflict: null } }]} />);
const pause = () => new Promise(resolve => setTimeout(resolve, 50));
const check = (condition: unknown, message: string) => { if (!condition) throw new Error(message); };
const click = (el: Element | null) => { check(el, 'Missing click target'); el!.dispatchEvent(new MouseEvent('click', { bubbles: true })); };
async function verify() {
  await pause();
  const svg = document.querySelector('svg[viewBox]')!;
  const edge = document.querySelector('g[data-edge-label][role="button"]')!;
  check(document.querySelectorAll('g[data-edge-label][role="button"]').length === 1, 'Expected one aggregate edge');
  check(edge.getAttribute('aria-label')?.includes('Holds Cognitive Emperor in (+2)'), 'Primary office label and count');
  const viewBox = svg.getAttribute('viewBox');
  click(edge.querySelector('text')); await pause();
  check(edge.getAttribute('aria-expanded') === 'true', 'Label click must expand');
  check(document.body.textContent?.includes('Derived office'), 'Derived provenance is visible');
  check(document.body.textContent?.includes('Explicit authored affiliation'), 'Authored details are retained');
  check(document.body.textContent?.includes('Branch: Navy'), 'Office branch context is visible');
  check(!document.querySelector('g[data-entity-node][aria-pressed="true"]'), 'Edge click must not focus a node');
  check(svg.getAttribute('viewBox') === viewBox, 'Edge click must not pan/zoom');
  click(Array.from(document.querySelectorAll('button')).find(b => b.textContent?.includes('Open Voltaire'))!); await pause();
  check(opened[0] === 'character', 'Character navigation');
  click(edge.querySelector('path')); await pause();
  check(edge.getAttribute('aria-expanded') === 'false', 'Path click collapses');
  edge.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true })); await pause();
  check(edge.getAttribute('aria-expanded') === 'true', 'Keyboard expands');
  click(Array.from(document.querySelectorAll('button')).find(b => b.textContent?.includes('Close'))!); await pause();
  check(edge.getAttribute('aria-expanded') === 'false', 'Close collapses');
  click(document.querySelector('g[data-entity-node]')); await pause();
  check(document.querySelector('g[data-entity-node][aria-pressed="true"]'), 'Node focus remains independent');
  document.getElementById('result')!.textContent = 'PASS: aggregate label/count; label/path/keyboard selection; expand/collapse; provenance; branch context; navigation; independent node focus and camera.';
}
void verify().catch(error => { document.getElementById('result')!.textContent = `FAIL: ${error.message}`; });
